/* The compact column representation is the extracted renderer-facing form of
 * FT2's normal bitmap-font contract: ASCII 32..90, uppercase UI labels, and a
 * fixed advance. The full tracker keeps its BMP decoder and Nordic mapping. */
static const uint8_t glyph[59][5]={{0},{0,0,95},{3,0,3},{20,127,20,127,20},{36,42,127,42,18},{35,19,8,100,98},{54,73,85,34,80},{0,3},{0,28,34,65},{0,65,34,28},{20,8,62,8,20},{8,8,62,8,8},{0,80,48},{8,8,8,8,8},{0,96,96},{32,16,8,4,2},{62,81,73,69,62},{0,66,127,64},{66,97,81,73,70},{33,65,69,75,49},{24,20,18,127,16},{39,69,69,69,57},{60,74,73,73,48},{1,113,9,5,3},{54,73,73,73,54},{6,73,73,41,30},{0,54,54},{0,86,54},{8,20,34,65},{20,20,20,20,20},{0,65,34,20,8},{2,1,81,9,6},{50,73,121,65,62},{126,17,17,17,126},{127,73,73,73,54},{62,65,65,65,34},{127,65,65,34,28},{127,73,73,73,65},{127,9,9,9,1},{62,65,73,73,122},{127,8,8,8,127},{0,65,127,65},{32,64,65,63,1},{127,8,20,34,65},{127,64,64,64,64},{127,2,12,2,127},{127,4,8,16,127},{62,65,65,65,62},{127,9,9,9,6},{62,65,81,33,94},{127,9,25,41,70},{70,73,73,73,49},{1,1,127,1,1},{63,64,64,64,63},{31,32,64,32,31},{63,64,56,64,63},{99,20,8,20,99},{7,8,112,8,7},{97,81,73,69,67}};
void ft2_ui_fill(ft2_ui_surface*s,int x,int y,int w,int h,uint8_t c){if(!s||!s->pixels)return;for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++){int px=x+xx,py=y+yy;if(px>=0&&py>=0&&px<s->width&&py<s->height)s->pixels[py*s->pitch+px]=c;}}
void ft2_ui_bevel(ft2_ui_surface*s,int x,int y,int w,int h,uint8_t f,uint8_t l,uint8_t d,bool p){ft2_ui_fill(s,x,y,w,h,f);ft2_ui_fill(s,x,y,w,1,p?d:l);ft2_ui_fill(s,x,y,1,h,p?d:l);ft2_ui_fill(s,x,y+h-1,w,1,d);ft2_ui_fill(s,x+w-1,y,1,h,d);}
bool ft2_ui_text_supported(const char*t){if(!t)return false;for(;*t;t++){unsigned char c=(unsigned char)toupper((unsigned char)*t);if(c<32||c>90)return false;}return true;}
void ft2_ui_text(ft2_ui_surface*s,int x,int y,const char*t,uint8_t c){if(!t)return;for(;*t;t++,x+=6){unsigned char ch=(unsigned char)toupper((unsigned char)*t);if(ch<32||ch>90)ch='?';for(int xx=0;xx<5;xx++)for(int yy=0;yy<7;yy++)if(glyph[ch-32][xx]&(1u<<yy))ft2_ui_fill(s,x+xx,y+yy,1,1,c);}}
void ft2_ui_scrollbar_set(ft2_ui_scrollbar*b,size_t n,size_t p,size_t pos){b->count=n;b->page=p?p:1;if(pos>n)pos=n;b->pos=pos;int track=b->h-2*b->arrows;if(track<1)track=1;b->thumb_h=n<=p?track:(int)((size_t)track*p/n);if(b->thumb_h<5)b->thumb_h=5;if(b->thumb_h>track)b->thumb_h=track;size_t end=n>p?n-p:0;if(b->pos>end)b->pos=end;b->thumb_y=b->y+b->arrows+(end?(int)((size_t)(track-b->thumb_h)*b->pos/end):0);}
bool ft2_ui_scrollbar_step(ft2_ui_scrollbar*b,int a){size_t old=b->pos,end=b->count>b->page?b->count-b->page:0;if(a<0){size_t d=(size_t)(-a);b->pos=d>b->pos?0:b->pos-d;}else if((size_t)a>end-b->pos)b->pos=end;else b->pos+=(size_t)a;ft2_ui_scrollbar_set(b,b->count,b->page,b->pos);return old!=b->pos;}
bool ft2_ui_scrollbar_press(ft2_ui_scrollbar*b,int x,int y){if(x<b->x||x>=b->x+b->w||y<b->y||y>=b->y+b->h)return false;if(y<b->y+b->arrows)return ft2_ui_scrollbar_step(b,-1);if(y>=b->y+b->h-b->arrows)return ft2_ui_scrollbar_step(b,1);if(y>=b->thumb_y&&y<b->thumb_y+b->thumb_h){b->dragging=true;b->drag_bias=y-b->thumb_y;return true;}return ft2_ui_scrollbar_step(b,y<b->thumb_y?-(int)b->page:(int)b->page);}
bool ft2_ui_scrollbar_drag(ft2_ui_scrollbar*b,int y){if(!b->dragging)return false;int track=b->h-2*b->arrows-b->thumb_h,at=y-b->y-b->arrows-b->drag_bias;if(at<0)at=0;if(at>track)at=track;size_t end=b->count>b->page?b->count-b->page:0;size_t pos=track?(size_t)at*end/(size_t)track:0;bool changed=pos!=b->pos;ft2_ui_scrollbar_set(b,b->count,b->page,pos);return changed;}
void ft2_ui_scrollbar_release(ft2_ui_scrollbar*b){b->dragging=false;}
void ft2_ui_scrollbar_draw(ft2_ui_surface*s,const ft2_ui_scrollbar*b,uint8_t f,uint8_t l,uint8_t d,uint8_t t){ft2_ui_bevel(s,b->x,b->y,b->w,b->h,f,l,d,false);ft2_ui_fill(s,b->x+2,b->thumb_y,b->w-4,b->thumb_h,t);ft2_ui_text(s,b->x+5,b->y+2,"^",d);ft2_ui_text(s,b->x+5,b->y+b->h-b->arrows+2,"V",d);}
